const commonJS = `
(() => {
  const icons = ${JSON.stringify(Object.fromEntries(['clock','arrow','close','pause','gift','infinity'].map(k=>[k,icon(k)])))};
  const feedbackImages = ${JSON.stringify(feedbackImages)};
  const labels = {ready:'แลกรางวัล',soldout:'หมดแล้ว',scheduled:'15/11 · 10:38 น.',insufficient:'แต้มไม่พอ',paused:'งดแลกชั่วคราว'};
  let currentState = 'ready';
  const dialog = document.querySelector('#reward-dialog');
  function setState(value) {
    currentState = value;
    document.querySelectorAll('.reward-card').forEach(card => {
      const gift = card.dataset.product === 'gift';
      card.dataset.state = value;
      const stock = card.querySelector('.stock');
      const button = card.querySelector('.redeem');
      const status = value === 'soldout' ? 'หมดแล้ว' : value === 'scheduled' ? 'เร็ว ๆ นี้' : gift ? 'เหลือ 8 ชิ้น' : 'ไม่จำกัด';
      const stockIcon = value === 'scheduled' ? 'clock' : value === 'soldout' ? 'close' : gift ? 'gift' : 'infinity';
      stock.innerHTML = icons[stockIcon] + '<span>' + status + '</span>';
      button.disabled = ['scheduled','paused'].includes(value);
      const actionIcon = value === 'scheduled' ? 'clock' : value === 'paused' ? 'pause' : value === 'soldout' ? 'close' : 'arrow';
      button.innerHTML = icons[actionIcon] + '<span>' + labels[value] + '</span>';
      button.setAttribute('aria-label', labels[value] + ' — ' + (gift ? 'บัตรโลตัส Gift Card' : 'ค่าอาหาร'));
    });
  }
  document.querySelector('#state-select').addEventListener('change', event => setState(event.target.value));
  document.querySelectorAll('.redeem').forEach(button => button.addEventListener('click', () => {
    if (button.disabled) return;
    const feedback = currentState === 'insufficient' || currentState === 'soldout';
    const gift = button.dataset.reward === 'gift';
    const mascot = document.querySelector('#dialog-mascot');
    const description = document.querySelector('#dialog-description');
    dialog.dataset.feedback = currentState;
    document.querySelector('.dialog-emblem').hidden = feedback;
    mascot.hidden = !feedback;
    description.hidden = feedback;
    if (feedback) {
      mascot.src = feedbackImages[currentState];
      document.querySelector('#dialog-title').textContent = currentState === 'insufficient' ? 'แต้มไม่พอ!' : 'ไม่ทันจ้า! มีคนตัดหน้า';
      document.querySelector('#dialog-close').textContent = currentState === 'insufficient' ? 'ไปทำงานก่อน' : 'รอรอบหน้า';
      description.textContent = '';
      dialog.removeAttribute('aria-describedby');
    } else {
      mascot.removeAttribute('src');
      document.querySelector('#dialog-title').textContent = 'ตัวอย่างการแลกรางวัล';
      document.querySelector('#dialog-close').textContent = 'ปิดตัวอย่าง';
      description.textContent = (gift ? 'บัตรโลตัส Gift Card · 260 แต้ม' : 'ค่าอาหาร · 300 แต้ม') + ' — หน้านี้เป็นตัวอย่างดีไซน์ ไม่มีการหักแต้มหรือจองรางวัล';
      dialog.setAttribute('aria-describedby', 'dialog-description');
    }
    dialog.showModal();
  }));
  document.querySelector('#dialog-close').addEventListener('click', () => dialog.close());
  dialog.addEventListener('click', event => { if (event.target === dialog) { const r = dialog.getBoundingClientRect(); if (event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom) dialog.close(); } });
  document.querySelectorAll('.size-control').forEach(button => button.addEventListener('click', () => {
    document.documentElement.style.setProperty('--card-width', button.dataset.width + 'px');
    document.querySelectorAll('.size-control').forEach(item=>item.setAttribute('aria-pressed', String(item === button)));
  }));
  const tiles = [...document.querySelectorAll('.design-tile')];
  if (tiles.length) {
    let saved = new Set();
    try { const parsed = JSON.parse(localStorage.getItem('cream-card-favorites') || '[]'); if (Array.isArray(parsed)) saved = new Set(parsed.filter(x=>Number.isInteger(x)&&x>=1&&x<=20)); } catch {}
    let group = 'ทั้งหมด';
    let onlySaved = false;
    const refresh = () => {
      let count = 0;
      tiles.forEach(tile => { tile.hidden = (group !== 'ทั้งหมด' && tile.dataset.group !== group) || (onlySaved && !saved.has(Number(tile.dataset.id))); if (!tile.hidden) count++; });
      document.querySelector('#result-count').textContent = count;
      document.querySelector('#saved-count').textContent = saved.size;
      document.querySelector('#empty-state').hidden = count > 0;
    };
    document.querySelectorAll('.favorite').forEach(button => {
      const id = Number(button.dataset.id);
      button.setAttribute('aria-pressed', String(saved.has(id)));
      button.addEventListener('click', () => {
        if (saved.has(id)) saved.delete(id); else saved.add(id);
        button.setAttribute('aria-pressed', String(saved.has(id)));
        try {localStorage.setItem('cream-card-favorites', JSON.stringify([...saved]));} catch {}
        refresh();
      });
    });
    document.querySelectorAll('.filter').forEach(button => button.addEventListener('click', () => {
      group = button.dataset.group;
      document.querySelectorAll('.filter').forEach(item=>item.setAttribute('aria-pressed', String(item === button)));
      refresh();
    }));
    document.querySelector('#saved-toggle').addEventListener('click', event => {onlySaved = !onlySaved; event.currentTarget.setAttribute('aria-pressed', String(onlySaved)); refresh();});
    refresh();
  }
  setState('ready');
})();
`;

const fonts = `<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Itim&family=Nunito:wght@400;600;700;800&display=swap" rel="stylesheet">`;
const brand = `<a class="brand" href="index.html"><span class="brand-mark">${icon('gift')}</span><span class="brand-name">Cream Rewards<span>ความสุขเล็ก ๆ จากทุกความตั้งใจ</span></span></a>`;
const stateSelect = `<label class="state-field" for="state-select">สถานะตัวอย่าง<select id="state-select"><option value="ready">พร้อมแลก</option><option value="scheduled">รอเปิดแลก</option><option value="soldout">หมดแล้ว</option><option value="insufficient">แต้มไม่พอ</option><option value="paused">งดแลกชั่วคราว</option></select></label>`;
const modal = `<dialog id="reward-dialog" class="dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description"><img id="dialog-mascot" class="dialog-mascot" alt="" width="150" height="150" hidden><div class="dialog-emblem">${icon('gift')}</div><h2 id="dialog-title">ตัวอย่างการแลกรางวัล</h2><p id="dialog-description"></p><button id="dialog-close" type="button" autofocus>ปิดตัวอย่าง</button></dialog>`;
const pair = d => `<div class="card-pair${d.id === 10 ? ' horizontal' : ''}">${rewards.map(r => card(d,r)).join('\n')}</div>`;
const head = (title, css) => `<!DOCTYPE html>\n<html lang="th">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<meta name="theme-color" content="#fff3ec">\n<meta name="description" content="ตัวอย่างการ์ดรางวัล Cream Rewards ธีมครีมพีช ออกแบบสำหรับมือถือ พร้อมตัวอย่างสถานะการแลก">\n<title>${title} · Cream Rewards</title>\n${fonts}\n<style>\n${baseCSS}\n${css}\n${shellCSS}\n</style>\n</head>`;

function gallery() {
  const filters = ['ทั้งหมด','เรียบง่าย','คูปอง','พิเศษ','สร้างสรรค์'].map((group,i)=>`<button type="button" class="filter" data-group="${group}" aria-pressed="${i === 0}">${group}${i === 0 ? ' · 20' : ''}</button>`).join('');
  const tiles = designs.map(d=>`<section class="design-tile" data-id="${d.id}" data-group="${d.group}"><div class="tile-top"><span class="tile-number">${n(d.id)}</span><div class="tile-heading"><h2><a href="${filename(d)}">${d.name}</a></h2><p>${d.thai}</p></div><button type="button" class="favorite" data-id="${d.id}" aria-label="บันทึกแบบ ${n(d.id)} ${d.name}" aria-pressed="false">${icon('heart')}</button></div><div class="tile-stage">${pair(d)}</div><div class="tile-bottom"><span class="group-tag">${d.group}</span><a class="tile-open" href="${filename(d)}">ดูแบบนี้ ${icon('external')}</a></div></section>`).join('\n');
  return `${head('การ์ดรางวัล 20 ดีไซน์', Object.values(designCSS).join('\n'))}\n<body id="top"><main class="page-shell"><header><div class="brand-row">${brand}<span class="collection-note">THE CARD COLLECTION / 2026</span></div><div class="hero"><div><div class="eyebrow">20 LITTLE WAYS TO SAY THANK YOU</div><h1>ของรางวัลที่คุ้นเคย<br><span>ในดีไซน์ใหม่ที่น่ารักกว่าเดิม</span></h1><p>20 แบบในธีมครีมพีช เลือกดู ลองเปลี่ยนสถานะ<br>แล้วเก็บแบบที่ชอบไว้เทียบกันได้เลย</p></div><div class="theme-note"><div class="swatches" aria-hidden="true"><span style="background:#fff3ec"></span><span style="background:#fbd3b9"></span><span style="background:#a85a2e"></span><span style="background:#ffe8a6"></span></div><div><b>ONE THEME. 20 PERSONALITIES.</b><small>ครีม · พีช · น้ำตาล · Itim</small></div></div></div></header><div class="toolbar"><nav class="filters" aria-label="หมวดดีไซน์">${filters}</nav>${stateSelect}</div><div class="results-line"><span><strong id="result-count">20</strong> ดีไซน์ <span aria-hidden="true">·</span> รางวัลพิเศษ &amp; รางวัลปกติ</span><button id="saved-toggle" class="saved-toggle" type="button" aria-pressed="false">${icon('heart')}ที่บันทึก <span id="saved-count">0</span></button></div><div class="gallery-grid">${tiles}</div><p class="empty" id="empty-state" hidden>ยังไม่มีแบบที่บันทึกในหมวดนี้<br>กดหัวใจบนดีไซน์ที่ชอบเพื่อเก็บไว้ดูด้วยกัน</p><footer class="gallery-footer"><span>ตัวอย่างดีไซน์ · กด “ดูแบบนี้” เพื่อเปิดไฟล์ HTML แยกแต่ละแบบ<br>ภาพรางวัลเป็นภาพประกอบจำลอง ราคาและสถานะเป็นข้อมูลตัวอย่าง</span><a href="#top">BACK TO TOP ↑</a></footer></main>${modal}<script>\n${commonJS}\n</script></body>\n</html>\n`;
}

function detail(d) {
  const prev = designs[(d.id + 18) % designs.length];
  const next = designs[d.id % designs.length];
  return `${head(`${n(d.id)} ${d.name}`, designCSS[d.id])}\n<body><main class="page-shell detail-shell"><div class="brand-row">${brand}<a class="back-link" href="index.html">${icon('back')}รวม 20 แบบ</a></div><header class="detail-header"><div><div class="eyebrow">THE CARD COLLECTION · ${d.group}</div><h1><span>${n(d.id)}</span>${d.name}</h1><p class="thai-title">${d.thai}</p><p class="detail-desc">${d.description}</p></div><a class="download-link" href="${filename(d)}" download>${icon('external')}บันทึกไฟล์ HTML</a></header><div class="detail-controls">${stateSelect}<div class="size-controls"><span>ความกว้างการ์ด</span>${[174,196,220].map((width,i)=>`<button class="size-control" type="button" data-width="${width}" aria-pressed="${i===0}">${width}px</button>`).join('')}</div></div><section class="detail-stage" aria-label="ตัวอย่างการ์ด ${d.name}">${pair(d)}</section><p class="sample-note">${icon('star')} ลองกดปุ่มแลกรางวัล หรือเปลี่ยนสถานะด้านบนได้ · ข้อมูลและภาพรางวัลเป็นตัวอย่าง</p><nav class="detail-nav" aria-label="ดูดีไซน์อื่น"><a href="${filename(prev)}">${icon('back')} ${n(prev.id)} ${prev.name}</a><a href="${filename(next)}">${n(next.id)} ${next.name} ${icon('arrow')}</a></nav></main>${modal}<script>\n${commonJS}\n</script></body>\n</html>\n`;
}

fs.writeFileSync(path.join(out,'index.html'),gallery());
for (const d of designs) fs.writeFileSync(path.join(out,filename(d)),detail(d));
fs.writeFileSync(path.join(out,'README.md'),`# Cream Rewards — การ์ดรางวัล 20 แบบ\n\nเปิด **index.html** เพื่อดูและเปรียบเทียบทั้ง 20 แบบ หรือเปิดไฟล์หมายเลข 01–20 เพื่อดูแต่ละดีไซน์\n\n- โทนเดียวกับ UI ปัจจุบัน: ครีม \`#FFF3EC\`, พีช \`#FBD3B9\`, ขอบ \`#F6D8C5\`, น้ำตาล \`#A85A2E\`\n- ฟอนต์ Itim + Nunito ตรงกับฝั่งพนักงานในโปรเจกต์\n- แต่ละไฟล์ HTML มี CSS, JavaScript และภาพ SVG ฝังในไฟล์ เปิดโดยดับเบิลคลิกได้ ไม่ต้องติดตั้งหรือรันเซิร์ฟเวอร์\n- ฟอนต์ Google Fonts โหลดเมื่อมีอินเทอร์เน็ต หากออฟไลน์จะใช้ Tahoma/ฟอนต์ระบบแทน\n- ทุกแบบมีตัวอย่างรางวัลพิเศษ (Gift Card) และรางวัลปกติ (ค่าอาหาร)\n- เปลี่ยนดูได้ 5 สถานะ: พร้อมแลก, รอเปิดแลก, หมดแล้ว, แต้มไม่พอ, งดแลกชั่วคราว\n- กำหนดรอบเปิดแลกเป็นข้อความตัวอย่าง 15/11 เวลา 10:38 น. ไม่มีการนับถอยหลังหรือเชื่อมต่อฐานข้อมูล\n- หน้ารวมกรองหมวด กดหัวใจเก็บแบบที่ชอบในเบราว์เซอร์ และเปิดแต่ละแบบได้\n- หน้าแยกปรับความกว้างการ์ด 174 / 196 / 220px ได้ โดยย่อให้พอดีจอมือถืออัตโนมัติ\n- ปุ่มแลกรางวัลเปิดหน้าต่างตัวอย่าง ไม่มีการหักแต้ม จองรางวัล หรือเขียนข้อมูลไปยังระบบจริง\n- ภาพบัตรของขวัญและอาหารเป็นภาพเวกเตอร์จำลองสำหรับเปรียบเทียบดีไซน์ เปลี่ยนเป็นรูปสินค้าจริงได้ภายหลัง\n\n## ไฟล์ตัวอย่าง\n\n| หมายเลข | ไฟล์ | แนวคิด |\n| --- | --- | --- |\n${designs.map(d=>`| ${n(d.id)} | [${filename(d)}](${filename(d)}) | ${d.thai} |`).join('\n')}\n\n## สร้างไฟล์ซ้ำ\n\nแก้ไข \`build.cjs\` แล้วรันจากโฟลเดอร์โปรเจกต์:\n\n\`\`\`sh\nnode reward-card-designs/build.cjs\n\`\`\`\n\nโฟลเดอร์นี้แยกจากแอป React เดิม ไม่ต้องใช้ Firebase และไม่มีขั้นตอน deploy\n`);
fs.appendFileSync(path.join(out,'README.md'), '\n## มาสคอตในป๊อปอัป\n\n- ใช้รูปต้นฉบับ `public/iconcry.png` และ `public/iconlol.png` ฝังเป็น PNG ใน HTML ทุกไฟล์ จึงเปิดไฟล์แยกได้โดยไม่ต้องคัดลอกโฟลเดอร์รูป\n- เลือกสถานะ **แต้มไม่พอ** แล้วกดปุ่มแลกรางวัล จะเห็น `iconcry` พร้อมข้อความ “แต้มไม่พอ!” และปุ่ม “ไปทำงานก่อน”\n- เลือกสถานะ **หมดแล้ว** แล้วกดปุ่ม “หมดแล้ว” จะเห็น `iconlol` พร้อมข้อความ “ไม่ทันจ้า! มีคนตัดหน้า” และปุ่ม “รอรอบหน้า”\n- ขนาดภาพ 150 × 150 พิกเซล กรอบป๊อปอัปและข้อความใช้รูปแบบเดียวกับแอปเดิม\n- สถานะรอเปิดแลกและงดแลกชั่วคราวยังปิดการกดปุ่มตามเดิม\n- หากสร้างไฟล์ใหม่ด้วย `build.cjs` ให้รันภายในโปรเจกต์เดิมที่มีรูปต้นฉบับใน `public/`\n');
console.log(`Generated ${designs.length} standalone designs + index.html in ${out}`);
